from math import gcd

def calculate_order(base, modulus):
    """Calculates the multiplicative order of base modulo modulus."""
    if gcd(base, modulus) != 1:
        return None

    # Euler's totient function phi(m)
    def euler_phi(n):
        result = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    phi = euler_phi(modulus)

    # Find divisors of phi
    divisors = []
    for i in range(1, int(phi**0.5) + 1):
        if phi % i == 0:
            divisors.append(i)
            if i * i != phi:
                divisors.append(phi // i)

    # Check powers
    for d in sorted(divisors):
        if pow(base, d, modulus) == 1:
            return d
    return phi # Should not happen if phi is correct

# Calculate k = ord_10000(3)
k_10000 = calculate_order(3, 10000)
print(f"Order of 3 modulo 10000 (k): {k_10000}")
